import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { AgGridProvider, AgGridReact } from "ag-grid-react";
import type { ColDef, GetRowIdParams, ValueFormatterParams } from "ag-grid-community";
import { AllEnterpriseModule } from "ag-grid-enterprise";
import { AgChartsCommunityModule } from "ag-charts-community";

// Sparklines and Integrated Charts need an AG Charts module
const modules = [AllEnterpriseModule.with(AgChartsCommunityModule)];

interface Holding {
  ticker: string;
  sector: string;
  quantity: number;
  price: number;
  purchasePrice: number;
  history: number[];
}

const usd = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });
// Value formatters must handle null and undefined (group rows, unloaded rows)
const currency = (p: ValueFormatterParams) => (p.value == null ? "" : usd.format(p.value));

export function PortfolioGrid() {
  const gridRef = useRef<AgGridReact<Holding>>(null);
  const [rowData] = useState<Holding[]>([
    { ticker: "AAPL", sector: "Technology", quantity: 120, price: 190.12, purchasePrice: 175.3, history: [182, 185, 188, 190] },
    { ticker: "MSFT", sector: "Technology", quantity: 80, price: 410.55, purchasePrice: 380.2, history: [400, 405, 408, 410] },
    { ticker: "JPM", sector: "Financials", quantity: 150, price: 198.4, purchasePrice: 185, history: [190, 194, 196, 198] },
  ]);

  const columnDefs = useMemo<ColDef<Holding>[]>(
    () => [
      { field: "sector", rowGroup: true, hide: true },
      { field: "ticker" },
      { field: "quantity", aggFunc: "sum" },
      { field: "price", valueFormatter: currency, enableCellChangeFlash: true },
      {
        colId: "marketValue",
        headerName: "Market value",
        valueGetter: (p) => (p.data ? p.data.quantity * p.data.price : null),
        valueFormatter: currency,
        aggFunc: "sum",
        cellRenderer: "agAnimateShowChangeCellRenderer",
      },
      {
        colId: "pnl",
        headerName: "P&L",
        valueGetter: (p) => (p.data ? (p.data.price - p.data.purchasePrice) * p.data.quantity : null),
        valueFormatter: currency,
        aggFunc: "sum",
      },
      { field: "history", headerName: "Trend", cellRenderer: "agSparklineCellRenderer", sortable: false },
    ],
    [],
  );

  const getRowId = useCallback((p: GetRowIdParams<Holding>) => p.data.ticker, []);

  // Hypothetical price feed: replace with your WebSocket handler
  useEffect(() => {
    const timer = setInterval(() => {
      const api = gridRef.current?.api;
      if (!api) return;
      const update: Holding[] = [];
      api.forEachLeafNode((node) => {
        if (node.data) update.push({ ...node.data, price: +(node.data.price * (1 + (Math.random() - 0.5) / 100)).toFixed(2) });
      });
      api.applyTransactionAsync({ update });
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  return (
    <AgGridProvider modules={modules}>
      <div style={{ height: 500 }}>
        <AgGridReact<Holding>
          ref={gridRef}
          rowData={rowData}
          columnDefs={columnDefs}
          getRowId={getRowId}
          groupDefaultExpanded={-1}
          grandTotalRow="bottom"
          cellSelection
          enableCharts
        />
      </div>
    </AgGridProvider>
  );
}
